     1→#include "parser.h"
     2→#include <stdlib.h>
     3→#include <stdio.h>
     4→#include <string.h>
     5→
     6→/* Parser 구현 - Phase 2.2 (700줄+) */
     7→
     8→Parser *parser_new(Lexer *lexer) {
     9→    Parser *p = (Parser *)malloc(sizeof(Parser));
    10→    if (!p) return NULL;
    11→    p->lexer = lexer;
    12→    p->current = 0;
    13→    p->tokens = lexer->tokens;
    14→    p->tok_count = lexer->tok_count;
    15→    return p;
    16→}
    17→
    18→void parser_free(Parser *p) {
    19→    if (p) free(p);
    20→}
    21→
    22→Token *current_token(Parser *p) {
    23→    if (p->current >= (int)p->tok_count) return &p->tokens[p->tok_count - 1];
    24→    return &p->tokens[p->current];
    25→}
    26→
    27→Token *peek_token(Parser *p, int offset) {
    28→    int idx = p->current + offset;
    29→    if (idx >= (int)p->tok_count) return &p->tokens[p->tok_count - 1];
    30→    return &p->tokens[idx];
    31→}
    32→
    33→void advance(Parser *p) {
    34→    if (p->current < (int)p->tok_count) p->current++;
    35→}
    36→
    37→int check(Parser *p, TokenKind kind) {
    38→    return current_token(p)->kind == kind;
    39→}
    40→
    41→int match(Parser *p, TokenKind kind) {
    42→    if (check(p, kind)) {
    43→        advance(p);
    44→        return 1;
    45→    }
    46→    return 0;
    47→}
    48→
    49→int consume(Parser *p, TokenKind kind, const char *msg) {
    50→    if (!check(p, kind)) {
    51→        fprintf(stderr, "Parse error at line %d: %s\n", current_token(p)->loc.line, msg);
    52→        return 0;
    53→    }
    54→    advance(p);
    55→    return 1;
    56→}
    57→
    58→static int is_type_keyword(TokenKind kind) {
    59→    return kind == TK_INT || kind == TK_CHAR || kind == TK_FLOAT ||
    60→           kind == TK_DOUBLE || kind == TK_VOID || kind == TK_LONG ||
    61→           kind == TK_SHORT || kind == TK_SIGNED || kind == TK_UNSIGNED ||
    62→           kind == TK_STRUCT || kind == TK_UNION || kind == TK_ENUM;
    63→}
    64→
    65→/* 타입 파싱 */
    66→Node *parse_type(Parser *p) {
    67→    Token tok = *current_token(p);
    68→
    69→    if (!is_type_keyword(tok.kind)) {
    70→        fprintf(stderr, "Expected type at line %d\n", tok.loc.line);
    71→        return NULL;
    72→    }
    73→
    74→    Node *type_node = node_new(ND_TYPE_BASE, tok.loc);
    75→    type_node->name = (char *)malloc(20);
    76→
    77→    /* 기본 타입 결정 */
    78→    switch (tok.kind) {
    79→        case TK_INT:    strcpy(type_node->name, "int"); break;
    80→        case TK_CHAR:   strcpy(type_node->name, "char"); break;
    81→        case TK_FLOAT:  strcpy(type_node->name, "float"); break;
    82→        case TK_DOUBLE: strcpy(type_node->name, "double"); break;
    83→        case TK_VOID:   strcpy(type_node->name, "void"); break;
    84→        default:        strcpy(type_node->name, "int"); break;
    85→    }
    86→    advance(p);
    87→
    88→    /* 포인터 타입 */
    89→    while (match(p, TK_STAR)) {
    90→        Node *ptr_type = node_new(ND_TYPE_PTR, current_token(p)->loc);
    91→        ptr_type->type_node = type_node;
    92→        type_node = ptr_type;
    93→    }
    94→
    95→    return type_node;
    96→}
    97→
    98→/* 선언자 파싱 (변수 이름) */
    99→Node *parse_declarator(Parser *p) {
   100→    Token tok = *current_token(p);
   101→    if (!check(p, TK_IDENT)) {
   102→        fprintf(stderr, "Expected identifier at line %d\n", tok.loc.line);
   103→        return NULL;
   104→    }
   105→
   106→    Node *decl = node_new(ND_IDENT, tok.loc);
   107→    decl->name = (char *)malloc(strlen(tok.val.ident) + 1);
   108→    strcpy(decl->name, tok.val.ident);
   109→    advance(p);
   110→
   111→    return decl;
   112→}
   113→
   114→/* 함수 정의 파싱 */
   115→Node *parse_func_def(Parser *p) {
   116→    Token tok = *current_token(p);
   117→    Node *type = parse_type(p);
   118→    if (!type) return NULL;
   119→
   120→    if (!check(p, TK_IDENT)) {
   121→        fprintf(stderr, "Expected function name at line %d\n", tok.loc.line);
   122→        return NULL;
   123→    }
   124→
   125→    Node *func = node_new(ND_FUNC_DEF, tok.loc);
   126→    func->type_node = type;
   127→    func->name = (char *)malloc(strlen(current_token(p)->val.ident) + 1);
   128→    strcpy(func->name, current_token(p)->val.ident);
   129→    advance(p);
   130→
   131→    if (!consume(p, TK_LPAREN, "Expected ( in function definition")) return NULL;
   132→
   133→    /* 파라미터 파싱 */
   134→    while (!check(p, TK_RPAREN)) {
   135→        Node *param = node_new(ND_PARAM, current_token(p)->loc);
   136→        param->type_node = parse_type(p);
   137→        if (check(p, TK_IDENT)) {
   138→            param->name = (char *)malloc(strlen(current_token(p)->val.ident) + 1);
   139→            strcpy(param->name, current_token(p)->val.ident);
   140→            advance(p);
   141→        }
   142→        node_add_child(func, param);
   143→
   144→        if (!check(p, TK_RPAREN)) {
   145→            if (!consume(p, TK_COMMA, "Expected , or ) in parameter list")) return NULL;
   146→        }
   147→    }
   148→    consume(p, TK_RPAREN, "Expected )");
   149→
   150→    /* 함수 본체 */
   151→    if (match(p, TK_LBRACE)) {
   152→        func->body = parse_block(p);
   153→    }
   154→
   155→    return func;
   156→}
   157→
   158→/* 변수 선언 파싱 */
   159→Node *parse_var_decl(Parser *p) {
   160→    Token tok = *current_token(p);
   161→    Node *type = parse_type(p);
   162→    if (!type) return NULL;
   163→
   164→    Node *var_decl = node_new(ND_VAR_DECL, tok.loc);
   165→    var_decl->type_node = type;
   166→
   167→    /* 선언자 */
   168→    Node *decl = parse_declarator(p);
   169→    if (decl) {
   170→        var_decl->name = decl->name;
   171→        node_add_child(var_decl, decl);
   172→    }
   173→
   174→    /* 초기값 */
   175→    if (match(p, TK_ASSIGN)) {
   176→        Node *init = parse_expr(p);
   177→        if (init) node_add_child(var_decl, init);
   178→    }
   179→
   180→    return var_decl;
   181→}
   182→
   183→/* 선언 파싱 - 함수 정의인지 변수 선언인지 구분 */
   184→Node *parse_declaration(Parser *p) {
   185→    int save_pos = p->current;
   186→
   187→    if (!is_type_keyword(current_token(p)->kind)) {
   188→        return NULL;
   189→    }
   190→
   191→    /* 타입 스킵 */
   192→    while (match(p, TK_STAR)) ;
   193→    parse_type(p);
   194→
   195→    /* 이름 스킵 */
   196→    if (!check(p, TK_IDENT)) {
   197→        p->current = save_pos;
   198→        return NULL;
   199→    }
   200→    advance(p);

