     1→/* C Self-Hosting Compiler - Main Driver */
     2→#include <stdio.h>
     3→#include <stdlib.h>
     4→#include <string.h>
     5→#include "lexer.h"
     6→#include "parser.h"
     7→#include "ir.h"
     8→#include "sema.h"
     9→#include "codegen.h"
    10→
    11→int main(int argc, char *argv[]) {
    12→    if (argc < 2) {
    13→        fprintf(stderr, "Usage: %s <input.c> [output.s]\n", argv[0]);
    14→        return 1;
    15→    }
    16→
    17→    const char *input_file = argv[1];
    18→    const char *output_file = (argc >= 3) ? argv[2] : "output.s";
    19→
    20→    /* Phase 1: Read source file */
    21→    FILE *fin = fopen(input_file, "r");
    22→    if (!fin) {
    23→        fprintf(stderr, "Error: Cannot open input file '%s'\n", input_file);
    24→        return 1;
    25→    }
    26→
    27→    fseek(fin, 0, SEEK_END);
    28→    long fsize = ftell(fin);
    29→    fseek(fin, 0, SEEK_SET);
    30→
    31→    char *source = (char *)malloc(fsize + 1);
    32→    if (!source) {
    33→        fprintf(stderr, "Error: Memory allocation failed\n");
    34→        fclose(fin);
    35→        return 1;
    36→    }
    37→
    38→    size_t read_size = fread(source, 1, fsize, fin);
    39→    source[read_size] = '\0';
    40→    fclose(fin);
    41→
    42→    /* Phase 2: Lexer */
    43→    Lexer *lexer = lexer_new(source, read_size);
    44→    if (!lexer) {
    45→        fprintf(stderr, "Error: Lexer initialization failed\n");
    46→        free(source);
    47→        return 1;
    48→    }
    49→
    50→    if (lexer_tokenize(lexer) != 0) {
    51→        fprintf(stderr, "Error: Tokenization failed\n");
    52→        lexer_free(lexer);
    53→        free(source);
    54→        return 1;
    55→    }
    56→
    57→    /* Phase 3: Parser */
    58→    Parser *parser = parser_new(lexer);
    59→    if (!parser) {
    60→        fprintf(stderr, "Error: Parser initialization failed\n");
    61→        lexer_free(lexer);
    62→        free(source);
    63→        return 1;
    64→    }
    65→
    66→    Node *program = parse_program(parser);
    67→    if (!program) {
    68→        fprintf(stderr, "Error: Parse failed\n");
    69→        parser_free(parser);
    70→        lexer_free(lexer);
    71→        free(source);
    72→        return 1;
    73→    }
    74→
    75→    /* Phase 4: IR Generation (AST -> CIR) */
    76→    CirModule *ir = cir_module_new();
    77→    if (!ir) {
    78→        fprintf(stderr, "Error: IR module creation failed\n");
    79→        node_free(program);
    80→        parser_free(parser);
    81→        lexer_free(lexer);
    82→        free(source);
    83→        return 1;
    84→    }
    85→
    86→    AstGen astgen = {0};
    87→    astgen.module = ir;
    88→    // Initialize variable tracking with initial capacity
    89→    astgen.var_cap = 16;
    90→    astgen.var_names = (char **)malloc(sizeof(char *) * 16);
    91→    astgen.var_ids = (uint32_t *)malloc(sizeof(uint32_t) * 16);
    92→    if (!astgen.var_names || !astgen.var_ids) {
    93→        fprintf(stderr, "Error: AstGen initialization failed\n");
    94→        cir_module_free(ir);
    95→        node_free(program);
    96→        parser_free(parser);
    97→        lexer_free(lexer);
    98→        free(source);
    99→        return 1;
   100→    }
   101→    astgen_program(&astgen, program);
   102→    free(astgen.var_names);
   103→    free(astgen.var_ids);
   104→
   105→    /* Phase 5: Semantic Analysis (skipped for now) */
   106→    Sema *sema = sema_new();
   107→    if (!sema) {
   108→        fprintf(stderr, "Error: Sema initialization failed\n");
   109→        cir_module_free(ir);
   110→        node_free(program);
   111→        parser_free(parser);
   112→        lexer_free(lexer);
   113→        free(source);
   114→        return 1;
   115→    }
   116→
   117→    /* Phase 6: Code Generation (CIR -> x86-64 Assembly) */
   118→    FILE *fout = fopen(output_file, "w");
   119→    if (!fout) {
   120→        fprintf(stderr, "Error: Cannot open output file '%s'\n", output_file);
   121→        sema_free(sema);
   122→        cir_module_free(ir);
   123→        node_free(program);
   124→        parser_free(parser);
   125→        lexer_free(lexer);
   126→        free(source);
   127→        return 1;
   128→    }
   129→
   130→    Codegen *codegen = codegen_new(ir, fout);
   131→    if (!codegen) {
   132→        fprintf(stderr, "Error: Codegen initialization failed\n");
   133→        fclose(fout);
   134→        sema_free(sema);
   135→        cir_module_free(ir);
   136→        node_free(program);
   137→        parser_free(parser);
   138→        lexer_free(lexer);
   139→        free(source);
   140→        return 1;
   141→    }
   142→
   143→    codegen_emit(codegen);
   144→
   145→    codegen_free(codegen);
   146→    fclose(fout);
   147→
   148→    /* Cleanup */
   149→    sema_free(sema);
   150→    cir_module_free(ir);
   151→    node_free(program);
   152→    parser_free(parser);
   153→    lexer_free(lexer);
   154→    free(source);
   155→
   156→    fprintf(stderr, "Compilation successful: %s -> %s\n", input_file, output_file);
   157→    return 0;
   158→}
