     1→#ifndef PARSER_H
     2→#define PARSER_H
     3→
     4→#include "lexer.h"
     5→#include "ast.h"
     6→
     7→/* Parser 상태 */
     8→typedef struct {
     9→    Lexer      *lexer;
    10→    int         current;        /* 현재 토큰 인덱스 */
    11→    Token      *tokens;         /* 렉서의 토큰 배열 (참조) */
    12→    size_t      tok_count;
    13→} Parser;
    14→
    15→/* Parser 함수 */
    16→Parser *parser_new(Lexer *lexer);
    17→void    parser_free(Parser *p);
    18→
    19→/* 파싱 진입점 */
    20→Node *parse_program(Parser *p);
    21→
    22→/* 선언 파싱 */
    23→Node *parse_declaration(Parser *p);
    24→Node *parse_func_def(Parser *p);
    25→Node *parse_var_decl(Parser *p);
    26→
    27→/* 문장 파싱 */
    28→Node *parse_statement(Parser *p);
    29→Node *parse_block(Parser *p);
    30→Node *parse_if_statement(Parser *p);
    31→Node *parse_while_statement(Parser *p);
    32→Node *parse_do_while_statement(Parser *p);
    33→Node *parse_for_statement(Parser *p);
    34→Node *parse_return_statement(Parser *p);
    35→
    36→/* 식 파싱 (연산자 우선순위) */
    37→Node *parse_expr(Parser *p);
    38→Node *parse_assign_expr(Parser *p);
    39→Node *parse_ternary_expr(Parser *p);
    40→Node *parse_logical_or_expr(Parser *p);
    41→Node *parse_logical_and_expr(Parser *p);
    42→Node *parse_bitwise_or_expr(Parser *p);
    43→Node *parse_bitwise_xor_expr(Parser *p);
    44→Node *parse_bitwise_and_expr(Parser *p);
    45→Node *parse_equality_expr(Parser *p);
    46→Node *parse_relational_expr(Parser *p);
    47→Node *parse_shift_expr(Parser *p);
    48→Node *parse_additive_expr(Parser *p);
    49→Node *parse_multiplicative_expr(Parser *p);
    50→Node *parse_unary_expr(Parser *p);
    51→Node *parse_postfix_expr(Parser *p);
    52→Node *parse_primary_expr(Parser *p);
    53→
    54→/* 타입 파싱 */
    55→Node *parse_type(Parser *p);
    56→Node *parse_declarator(Parser *p);
    57→
    58→/* 헬퍼 */
    59→Token *current_token(Parser *p);
    60→Token *peek_token(Parser *p, int offset);
    61→void advance(Parser *p);
    62→int match(Parser *p, TokenKind kind);
    63→int check(Parser *p, TokenKind kind);
    64→int consume(Parser *p, TokenKind kind, const char *msg);
    65→
    66→#endif /* PARSER_H */
