   200→    advance(p);
   201→
   202→    /* ( 다음에 오는지 확인 */
   203→    int is_func = check(p, TK_LPAREN);
   204→    p->current = save_pos;
   205→
   206→    if (is_func) {
   207→        return parse_func_def(p);
   208→    } else {
   209→        Node *var = parse_var_decl(p);
   210→        if (var && !consume(p, TK_SEMICOLON, "Expected ; after variable declaration")) {
   211→            return NULL;
   212→        }
   213→        return var;
   214→    }
   215→}
   216→
   217→/* 프로그램 파싱 */
   218→Node *parse_program(Parser *p) {
   219→    Token tok = *current_token(p);
   220→    Node *program = node_new(ND_PROGRAM, tok.loc);
   221→
   222→    while (!check(p, TK_EOF)) {
   223→        Node *decl = parse_declaration(p);
   224→        if (decl) {
   225→            node_add_child(program, decl);
   226→        } else {
   227→            advance(p);  /* 에러 시 전진 */
   228→        }
   229→    }
   230→
   231→    return program;
   232→}
   233→
   234→/* 블록 파싱 { ... } */
   235→Node *parse_block(Parser *p) {
   236→    Token tok = *current_token(p);
   237→    Node *block = node_new(ND_BLOCK, tok.loc);
   238→
   239→    while (!check(p, TK_RBRACE) && !check(p, TK_EOF)) {
   240→        /* 변수 선언인지 문장인지 구분 */
   241→        if (is_type_keyword(current_token(p)->kind)) {
   242→            Node *decl = parse_var_decl(p);
   243→            if (decl) {
   244→                consume(p, TK_SEMICOLON, "Expected ; after variable declaration");
   245→                node_add_child(block, decl);
   246→            }
   247→        } else {
   248→            Node *stmt = parse_statement(p);
   249→            if (stmt) node_add_child(block, stmt);
   250→        }
   251→    }
   252→
   253→    if (!consume(p, TK_RBRACE, "Expected }")) return NULL;
   254→    return block;
   255→}
   256→
   257→/* 문장 파싱 */
   258→Node *parse_statement(Parser *p) {
   259→    if (check(p, TK_IF)) return parse_if_statement(p);
   260→    if (check(p, TK_WHILE)) return parse_while_statement(p);
   261→    if (check(p, TK_DO)) return parse_do_while_statement(p);
   262→    if (check(p, TK_FOR)) return parse_for_statement(p);
   263→    if (check(p, TK_RETURN)) return parse_return_statement(p);
   264→    if (check(p, TK_BREAK)) {
   265→        Node *brk = node_new(ND_BREAK, current_token(p)->loc);
   266→        advance(p);
   267→        consume(p, TK_SEMICOLON, "Expected ; after break");
   268→        return brk;
   269→    }
   270→    if (check(p, TK_CONTINUE)) {
   271→        Node *cont = node_new(ND_CONTINUE, current_token(p)->loc);
   272→        advance(p);
   273→        consume(p, TK_SEMICOLON, "Expected ; after continue");
   274→        return cont;
   275→    }
   276→    if (check(p, TK_LBRACE)) {
   277→        advance(p);
   278→        return parse_block(p);
   279→    }
   280→
   281→    /* 식 문장 */
   282→    Node *expr = parse_expr(p);
   283→    consume(p, TK_SEMICOLON, "Expected ; after expression");
   284→    if (expr) {
   285→        Node *expr_stmt = node_new(ND_EXPR_STMT, expr->loc);
   286→        expr_stmt->left = expr;
   287→        return expr_stmt;
   288→    }
   289→    return NULL;
   290→}
   291→
   292→/* If 문장 파싱 */
   293→Node *parse_if_statement(Parser *p) {
   294→    Token tok = *current_token(p);
   295→    Node *if_stmt = node_new(ND_IF, tok.loc);
   296→
   297→    if (!consume(p, TK_IF, "Expected if")) return NULL;
   298→    if (!consume(p, TK_LPAREN, "Expected ( after if")) return NULL;
   299→
   300→    if_stmt->cond = parse_expr(p);
   301→
   302→    if (!consume(p, TK_RPAREN, "Expected ) after if condition")) return NULL;
   303→
   304→    if_stmt->then_body = parse_statement(p);
   305→
   306→    if (match(p, TK_ELSE)) {
   307→        if_stmt->else_body = parse_statement(p);
   308→    }
   309→
   310→    return if_stmt;
   311→}
   312→
   313→/* While 문장 파싱 */
   314→Node *parse_while_statement(Parser *p) {
   315→    Token tok = *current_token(p);
   316→    Node *while_stmt = node_new(ND_WHILE, tok.loc);
   317→
   318→    if (!consume(p, TK_WHILE, "Expected while")) return NULL;
   319→    if (!consume(p, TK_LPAREN, "Expected ( after while")) return NULL;
   320→
   321→    while_stmt->cond = parse_expr(p);
   322→
   323→    if (!consume(p, TK_RPAREN, "Expected ) after while condition")) return NULL;
   324→
   325→    while_stmt->body = parse_statement(p);
   326→
   327→    return while_stmt;
   328→}
   329→
   330→/* Do-while 문장 파싱 */
   331→Node *parse_do_while_statement(Parser *p) {
   332→    Token tok = *current_token(p);
   333→    Node *do_while = node_new(ND_DO_WHILE, tok.loc);
   334→
   335→    if (!consume(p, TK_DO, "Expected do")) return NULL;
   336→
   337→    do_while->body = parse_statement(p);
   338→
   339→    if (!consume(p, TK_WHILE, "Expected while after do body")) return NULL;
   340→    if (!consume(p, TK_LPAREN, "Expected ( after while")) return NULL;
   341→
   342→    do_while->cond = parse_expr(p);
   343→
   344→    if (!consume(p, TK_RPAREN, "Expected ) after while condition")) return NULL;
   345→    if (!consume(p, TK_SEMICOLON, "Expected ; after do-while")) return NULL;
