   350→/* For 문장 파싱 */
   351→Node *parse_for_statement(Parser *p) {
   352→    Token tok = *current_token(p);
   353→    Node *for_stmt = node_new(ND_FOR, tok.loc);
   354→
   355→    if (!consume(p, TK_FOR, "Expected for")) return NULL;
   356→    if (!consume(p, TK_LPAREN, "Expected ( after for")) return NULL;
   357→
   358→    /* 초기화 */
   359→    if (is_type_keyword(current_token(p)->kind)) {
   360→        for_stmt->init = parse_var_decl(p);
   361→    } else if (!check(p, TK_SEMICOLON)) {
   362→        for_stmt->init = parse_expr(p);
   363→    }
   364→    consume(p, TK_SEMICOLON, "Expected ; after for init");
   365→
   366→    /* 조건 */
   367→    if (!check(p, TK_SEMICOLON)) {
   368→        for_stmt->cond = parse_expr(p);
   369→    }
   370→    consume(p, TK_SEMICOLON, "Expected ; after for condition");
   371→
   372→    /* 스텝 */
   373→    if (!check(p, TK_RPAREN)) {
   374→        for_stmt->step = parse_expr(p);
   375→    }
   376→    consume(p, TK_RPAREN, "Expected ) after for clauses");
   377→
   378→    /* 본체 */
   379→    for_stmt->body = parse_statement(p);
   380→
   381→    return for_stmt;
   382→}
