   405→/* 할당 (=, +=, -=, 등) */
   406→Node *parse_assign_expr(Parser *p) {
   407→    Node *left = parse_ternary_expr(p);
   408→
   409→    while (current_token(p)->kind == TK_ASSIGN ||
   410→           current_token(p)->kind == TK_PLUS_ASSIGN ||
   411→           current_token(p)->kind == TK_MINUS_ASSIGN) {
