   413→        advance(p);
   414→        Node *right = parse_ternary_expr(p);
   415→
   416→        Node *assign = node_new(ND_ASSIGN, op_tok.loc);
   417→        assign->left = left;
   418→        assign->right = right;
   419→        assign->op = op_tok.kind;
   420→        left = assign;
   421→    }
   422→
   423→    return left;
   424→}
