   634→/* 단항 연산자 (-, !, ~, &, *, ++, --) */
   635→Node *parse_unary_expr(Parser *p) {
   636→    Token tok = *current_token(p);
   637→
   638→    if (check(p, TK_MINUS) || check(p, TK_PLUS) || check(p, TK_BANG) ||
   639→        check(p, TK_TILDE) || check(p, TK_AMPERSAND) || check(p, TK_STAR)) {
   640→        TokenKind op = tok.kind;
   641→        advance(p);
   642→        Node *expr = parse_unary_expr(p);
   643→
   644→        Node *unary = node_new(ND_UNARY, tok.loc);
   645→        unary->left = expr;
   646→        unary->op = op;
   647→        unary->is_prefix = 1;
   648→        return unary;
   649→    }
   650→
   651→    if (check(p, TK_INC) || check(p, TK_DEC)) {
   652→        TokenKind op = tok.kind;
   653→        advance(p);
   654→        Node *expr = parse_unary_expr(p);
   655→
   656→        Node *unary = node_new(ND_UNARY, tok.loc);
   657→        unary->left = expr;
   658→        unary->op = op;
   659→        unary->is_prefix = 1;
   660→        return unary;
   661→    }
   662→
   663→    if (check(p, TK_SIZEOF)) {
   664→        advance(p);
   665→        Node *sizeof_node = node_new(ND_SIZEOF_EXPR, tok.loc);
   666→        sizeof_node->left = parse_unary_expr(p);
   667→        return sizeof_node;
   668→    }
   669→
   670→    return parse_postfix_expr(p);
   671→}
