   673→/* 후위 연산자 (++, --, [], ., ->, ()) */
   674→Node *parse_postfix_expr(Parser *p) {
   675→    Node *left = parse_primary_expr(p);
   676→
   677→    while (1) {
   678→        if (check(p, TK_INC) || check(p, TK_DEC)) {
   679→            Token op_tok = *current_token(p);
   680→            TokenKind op = op_tok.kind;
   681→            advance(p);
   682→
   683→            Node *unary = node_new(ND_UNARY, op_tok.loc);
   684→            unary->left = left;
   685→            unary->op = op;
   686→            unary->is_prefix = 0;  /* 후위 */
   687→            left = unary;
   688→        }
   689→        else if (match(p, TK_LBRACKET)) {
   690→            Token idx_tok = *peek_token(p, -1);
   691→            Node *index = node_new(ND_INDEX, idx_tok.loc);
   692→            index->left = left;
   693→            index->right = parse_expr(p);
   694→            consume(p, TK_RBRACKET, "Expected ]");
   695→            left = index;
   696→        }
   697→        else if (match(p, TK_LPAREN)) {
   698→            Token call_tok = *peek_token(p, -1);
   699→            Node *call = node_new(ND_CALL, call_tok.loc);
   700→            call->left = left;
   701→
   702→            /* 인수 파싱 */
   703→            while (!check(p, TK_RPAREN)) {
   704→                Node *arg = parse_assign_expr(p);
   705→                if (arg) node_add_child(call, arg);
   706→
   707→                if (!check(p, TK_RPAREN)) {
   708→                    if (!consume(p, TK_COMMA, "Expected , or ) in function call")) {
   709→                        break;
   710→                    }
   711→                }
   712→            }
   713→            consume(p, TK_RPAREN, "Expected )");
   714→            left = call;
   715→        }
   716→        else if (match(p, TK_DOT)) {
   717→            Token mem_tok = *current_token(p);
   718→            if (!check(p, TK_IDENT)) {
   719→                fprintf(stderr, "Expected identifier after .\n");
   720→                return left;
   721→            }
   722→            Node *member = node_new(ND_MEMBER, mem_tok.loc);
   723→            member->left = left;
   724→            member->name = (char *)malloc(strlen(mem_tok.val.ident) + 1);
   725→            strcpy(member->name, mem_tok.val.ident);
   726→            advance(p);
   727→            left = member;
   728→        }
   729→        else if (match(p, TK_ARROW)) {
   730→            Token mem_tok = *current_token(p);
   731→            if (!check(p, TK_IDENT)) {
   732→                fprintf(stderr, "Expected identifier after ->\n");
   733→                return left;
   734→            }
   735→            Node *arrow = node_new(ND_ARROW, mem_tok.loc);
   736→            arrow->left = left;
   737→            arrow->name = (char *)malloc(strlen(mem_tok.val.ident) + 1);
   738→            strcpy(arrow->name, mem_tok.val.ident);
   739→            advance(p);
   740→            left = arrow;
   741→        }
   742→        else {
   743→            break;
   744→        }
   745→    }
   746→
   747→    return left;
   748→}
