   750→/* 기본 식 (literals, identifiers, parenthesized expressions) */
   751→Node *parse_primary_expr(Parser *p) {
   752→    Token tok = *current_token(p);
   753→
   754→    if (check(p, TK_INT_LIT)) {
   755→        Node *lit = node_new(ND_INT_LIT, tok.loc);
   756→        lit->int_val = tok.val.int_val;
   757→        advance(p);
   758→        return lit;
   759→    }
   760→
   761→    if (check(p, TK_FLOAT_LIT)) {
   762→        Node *lit = node_new(ND_FLOAT_LIT, tok.loc);
   763→        lit->float_val = tok.val.float_val;
   764→        advance(p);
   765→        return lit;
   766→    }
   767→
   768→    if (check(p, TK_CHAR_LIT)) {
   769→        Node *lit = node_new(ND_CHAR_LIT, tok.loc);
   770→        lit->char_val = tok.val.char_val;
   771→        advance(p);
   772→        return lit;
   773→    }
   774→
   775→    if (check(p, TK_STR_LIT)) {
   776→        Node *lit = node_new(ND_STR_LIT, tok.loc);
   777→        lit->str_val = (char *)malloc(strlen(tok.val.str_val) + 1);
   778→        strcpy(lit->str_val, tok.val.str_val);
   779→        advance(p);
   780→        return lit;
   781→    }
   782→
   783→    if (check(p, TK_IDENT)) {
   784→        Node *ident = node_new(ND_IDENT, tok.loc);
   785→        ident->name = (char *)malloc(strlen(tok.val.ident) + 1);
   786→        strcpy(ident->name, tok.val.ident);
   787→        advance(p);
   788→        return ident;
   789→    }
   790→
   791→    if (match(p, TK_LPAREN)) {
   792→        Node *expr = parse_expr(p);
   793→        consume(p, TK_RPAREN, "Expected )");
   794→        return expr;
   795→    }
   796→
   797→    fprintf(stderr, "Unexpected token at line %d\n", tok.loc.line);
   798→    return NULL;
   799→}

