    28→/* 키워드 조회 */
    29→static TokenKind lookup_keyword(const char *name, size_t len) {
    30→    for (int i = 0; keywords[i].name; i++) {
    31→        if (strlen(keywords[i].name) == len &&
    32→            strncmp(keywords[i].name, name, len) == 0) {
    33→            return keywords[i].kind;
    34→        }
    35→    }
    36→    return TK_UNKNOWN;  /* 키워드 아님 (식별자) */
    37→}
