    39→/* Lexer 생성 */
    40→Lexer *lexer_new(const char *src, size_t len) {
    41→    Lexer *l = (Lexer *)malloc(sizeof(Lexer));
    42→    if (!l) return NULL;
    43→
    44→    l->src = src;
    45→    l->src_len = len;
    46→    l->pos = 0;
    47→    l->line = 1;
    48→    l->col = 0;
    49→
    50→    l->tok_cap = 1024;
    51→    l->tokens = (Token *)malloc(sizeof(Token) * l->tok_cap);
    52→    if (!l->tokens) {
    53→        free(l);
    54→        return NULL;
    55→    }
    56→    l->tok_count = 0;
    57→
    58→    return l;
    59→}
    60→
    61→/* Lexer 해제 */
    62→void lexer_free(Lexer *l) {
    63→    if (!l) return;
    64→    for (size_t i = 0; i < l->tok_count; i++) {
    65→        if (l->tokens[i].kind == TK_IDENT && l->tokens[i].val.ident) {
    66→            free(l->tokens[i].val.ident);
    67→        } else if (l->tokens[i].kind == TK_STR_LIT && l->tokens[i].val.str_val) {
    68→            free(l->tokens[i].val.str_val);
    69→        }
    70→    }
    71→    free(l->tokens);
    72→    free(l);
    73→}
    74→
    75→/* Token 추가 */
    76→static void add_token(Lexer *l, Token tok) {
    77→    if (l->tok_count >= l->tok_cap) {
    78→        l->tok_cap *= 2;
    79→        Token *new_tokens = (Token *)realloc(l->tokens, sizeof(Token) * l->tok_cap);
    80→        if (!new_tokens) return;
    81→        l->tokens = new_tokens;
    82→    }
    83→    l->tokens[l->tok_count++] = tok;
    84→}
    85→
    86→/* 현재 문자 */
    87→static char current(Lexer *l) {
    88→    return l->pos < l->src_len ? l->src[l->pos] : '\0';
    89→}
    90→
    91→/* 다음 문자 */
    92→static char peek(Lexer *l, int offset) {
    93→    return l->pos + offset < l->src_len ? l->src[l->pos + offset] : '\0';
