} CompilerContext;

#define CLEANUP_AND_RETURN(ctx, msg, code) \
    do { \
        fprintf(stderr, "Error: %s\n", msg); \
        context_free(&ctx); \
        return code; \
    } while(0)

// Usage:
if (!fin) CLEANUP_AND_RETURN(ctx, "Cannot open input", 1);
if (!lexer) CLEANUP_AND_RETURN(ctx, "Lexer init failed", 1);
