/**
 * Generic binary operator parser
 *
 * Parses expressions with binary operators at a single precedence level.
 *
 * Example:
 *   parse_expr -> parse_assign
 *   parse_assign -> parse_ternary
 *   parse_ternary -> parse_logical_or
 *   ...
 *   parse_multiplicative -> parse_unary
 *
 * This function handles all the "parse_*_expr" functions by parameterizing:
 * - next_level: function to parse the next precedence level
 * - ops: array of operators to check for at this level
 * - op_count: size of ops array
 */
static Node *parse_binary_expr_generic(Parser *p,
                                       Node *(*next_level)(Parser *),
                                       const TokenKind *ops,
                                       int op_count) {
    Node *left = next_level(p);

    while (1) {
        /* Check if current token is one of our operators */
        int found = 0;
        for (int i = 0; i < op_count; i++) {
            if (check(p, ops[i])) {
                found = 1;
                break;
            }
        }
        if (!found) break;

        Token op_tok = *current_token(p);
        advance(p);
        Node *right = next_level(p);

        Node *binary = node_new(ND_BINARY, op_tok.loc);
        binary->left = left;
        binary->right = right;
        binary->op = op_tok.kind;
        left = binary;
    }

    return left;
}

/* === Replace 10 functions with 1-line wrappers === */

Node *parse_logical_or_expr(Parser *p) {
    static const TokenKind ops[] = {TK_OR};
    return parse_binary_expr_generic(p, parse_logical_and_expr, ops, 1);
}

Node *parse_logical_and_expr(Parser *p) {
    static const TokenKind ops[] = {TK_AND};
    return parse_binary_expr_generic(p, parse_bitwise_or_expr, ops, 1);
}

Node *parse_bitwise_or_expr(Parser *p) {
    static const TokenKind ops[] = {TK_PIPE};
    return parse_binary_expr_generic(p, parse_bitwise_xor_expr, ops, 1);
}

Node *parse_bitwise_xor_expr(Parser *p) {
    static const TokenKind ops[] = {TK_CARET};
    return parse_binary_expr_generic(p, parse_bitwise_and_expr, ops, 1);
}

Node *parse_bitwise_and_expr(Parser *p) {
    static const TokenKind ops[] = {TK_AMPERSAND};
    return parse_binary_expr_generic(p, parse_equality_expr, ops, 1);
}

Node *parse_equality_expr(Parser *p) {
    static const TokenKind ops[] = {TK_EQ, TK_NEQ};
    return parse_binary_expr_generic(p, parse_relational_expr, ops, 2);
}

Node *parse_relational_expr(Parser *p) {
    static const TokenKind ops[] = {TK_LT, TK_LE, TK_GT, TK_GE};
    return parse_binary_expr_generic(p, parse_shift_expr, ops, 4);
}

Node *parse_shift_expr(Parser *p) {
    static const TokenKind ops[] = {TK_LSHIFT, TK_RSHIFT};
    return parse_binary_expr_generic(p, parse_additive_expr, ops, 2);
}

Node *parse_additive_expr(Parser *p) {
    static const TokenKind ops[] = {TK_PLUS, TK_MINUS};
    return parse_binary_expr_generic(p, parse_multiplicative_expr, ops, 2);
}

Node *parse_multiplicative_expr(Parser *p) {
    static const TokenKind ops[] = {TK_STAR, TK_SLASH, TK_PERCENT};
    return parse_binary_expr_generic(p, parse_unary_expr, ops, 3);
}
