```c
/**
 * Internal helper: allocate and initialize SemaType
 * Sets all fields to default values
 */
static SemaType *_sema_type_alloc(void) {
    SemaType *t = (SemaType *)malloc(sizeof(SemaType));
    if (!t) return NULL;

    /* Initialize all fields to sensible defaults */
    t->kind = SEMA_TYPE_UNKNOWN;
    t->base = NULL;
    t->array_size = 0;
    t->is_const = 0;

    return t;
}

SemaType *sema_type_basic(SemaTypeKind kind) {
    SemaType *t = _sema_type_alloc();
    if (t) t->kind = kind;
    return t;
}

SemaType *sema_type_ptr(SemaType *base) {
    if (!base) return NULL;
    SemaType *t = _sema_type_alloc();
    if (t) {
        t->kind = SEMA_TYPE_PTR;
        t->base = base;
    }
    return t;
}

SemaType *sema_type_array(SemaType *base, int size) {
    if (!base) return NULL;
    SemaType *t = _sema_type_alloc();
    if (t) {
        t->kind = SEMA_TYPE_ARRAY;
        t->base = base;
        t->array_size = size;
    }
    return t;
}
```

**Impact**:
- Before: 31 LOC (repetition in 3 functions)
- After: 19 LOC (helper + 3 functions)
- **Savings**: 12 LOC
- **Benefits**:
  - Adding new field: update `_sema_type_alloc()` once
  - Consistency guaranteed (all types initialized identically)

